import test from "node:test";
import assert from "node:assert/strict";
import { drain } from "../src/queue.js";

// 现有 tests/queue.test.js 的断言对「串行 await」和「并发启动+按下标回填」都能通过，
// 因此无法锁定 queue.js 顶部注释写明的「依次跑完」语义。这里补两条能区分二者的用例。

test("drain 串行执行：同一时刻只跑一个任务", async () => {
  let inFlight = 0;
  let peak = 0;
  const jobs = [1, 2, 3, 4, 5];
  const handler = (n) =>
    new Promise((r) =>
      setTimeout(() => {
        peak = Math.max(peak, inFlight);
        inFlight -= 1;
        r(n);
      }, 5)
    );

  // 进任务前登记并发，退出时减
  const tracked = (n) => {
    inFlight += 1;
    return handler(n);
  };

  assert.deepEqual(await drain(jobs, tracked), [1, 2, 3, 4, 5]);
  assert.equal(peak, 1, `期望峰值并发为 1（依次跑完），实际 ${peak}`);
});

test("drain 不泄漏未完成的可变数组引用", async () => {
  // 旧实现返回的是同一个数组引用，调用方在 await 之后仍会看到后续 push 进去的元素。
  const jobs = [1, 2, 3];
  const result = await drain(jobs, (n) =>
    new Promise((r) => setTimeout(() => r(n), 5))
  );
  const snapshot = [...result];
  await new Promise((r) => setTimeout(r, 30));
  assert.deepEqual(result, snapshot, "drain 返回的数组不应在返回后继续被填充");
  assert.equal(result.length, 3);
});

test("drain 在 handler 抛错时 reject", async () => {
  const boom = new Error("boom");
  await assert.rejects(
    drain([1, 2, 3], (n) => (n === 2 ? Promise.reject(boom) : Promise.resolve(n))),
    (err) => err === boom
  );
});

