// 依次跑完所有任务再 resolve。handler 可能是异步的。
export async function drain(jobs, handler) {
  const done = [];
  for (const j of jobs) {
    // 逐个 await：串行执行，既保证全部跑完才返回，也天然保持提交顺序。
    done.push(await handler(j));
  }
  return done;
}
